-- migration_74_mental_health_note_full_196.sql
-- Full replacement of mental_health_note for all 196 weeks (week_number 1-196),
-- authored by Roop, delivered 2026-09-23 as Moms_Village_Mental_Health_Notes_196_Weeks.docx.
-- Replaces the prior partial coverage (week_number 119-196 only, from migrations 43/44/45/46)
-- with a full, consistent-voice pass across pregnancy weeks 1-39 and postpartum weeks 0-156
-- (week_number 40-196). Idempotent, safe to rerun.

update care_chart_week_content set mental_health_note = 'The earliest pregnancy weeks are counted before you may know you are pregnant. Looking back, there is no feeling you were supposed to have had at the start.' where week_number = 1;
update care_chart_week_content set mental_health_note = 'Waiting to know whether you are pregnant can leave little room for anything else. You can choose how much of that waiting to share, and with whom.' where week_number = 2;
update care_chart_week_content set mental_health_note = 'When there is little certainty, other people''s confident predictions may feel unhelpful. It is okay to ask for company without guesses about what will happen.' where week_number = 3;
update care_chart_week_content set mental_health_note = 'Pregnancy news can bring delight, uncertainty, a blank feeling or several reactions together. You do not have to settle on one response before speaking to someone you trust.' where week_number = 4;
update care_chart_week_content set mental_health_note = 'A wanted pregnancy can still change plans you cared about. Having feelings about those changes does not cancel out what this baby means to you.' where week_number = 5;
update care_chart_week_content set mental_health_note = 'If tiredness or nausea is narrowing your day, it may affect your patience too. Asking someone to take over an ordinary task can make room for more than simply getting through it.' where week_number = 6;
update care_chart_week_content set mental_health_note = 'Keeping pregnancy private can mean carrying questions quietly. You can tell one trusted person without being ready to tell everyone.' where week_number = 7;
update care_chart_week_content set mental_health_note = 'An early appointment may bring reassurance and new questions together. You can ask for explanations again; understanding your care does not require getting everything in one conversation.' where week_number = 8;
update care_chart_week_content set mental_health_note = 'If you have been pregnant before, this experience may bring back feelings from that time. You can tell your healthcare professional what you would like them to understand about your history.' where week_number = 9;
update care_chart_week_content set mental_health_note = 'You do not have to enjoy every physical change to care about your pregnancy. Neutral words about your body may fit better than being asked to love every moment.' where week_number = 10;
update care_chart_week_content set mental_health_note = 'Waiting for results can draw your attention back to the same questions. If worry is taking over rest or everyday life, tell your healthcare professional; you need not manage it silently.' where week_number = 11;
update care_chart_week_content set mental_health_note = 'Sharing the news can bring more attention than you want. You are allowed to decide which questions to answer and which parts of this pregnancy stay yours.' where week_number = 12;
update care_chart_week_content set mental_health_note = 'The end of a trimester is a calendar marker, not an emotional deadline. You do not have to feel more relaxed, energetic or connected because a new week has arrived.' where week_number = 13;
update care_chart_week_content set mental_health_note = 'If some energy returns, it need not immediately become extra work. You can leave room for something that makes the day feel like your own.' where week_number = 14;
update care_chart_week_content set mental_health_note = 'Comments about your size or appearance can land differently each day. A simple "I''d rather not discuss my body" is enough; you do not owe a longer explanation.' where week_number = 15;
update care_chart_week_content set mental_health_note = 'Connection with a baby you have not met can feel vivid, distant or changeable. There is no particular feeling you must produce to prove you are becoming a mother.' where week_number = 16;
update care_chart_week_content set mental_health_note = 'Practical planning can crowd out conversations about you. You might tell someone close what you are curious about, looking forward to or finding unfamiliar in this change.' where week_number = 17;
update care_chart_week_content set mental_health_note = 'Around scans or appointments, you may want company, privacy or time before discussing anything. Letting someone know your preference can make their support more useful.' where week_number = 18;
update care_chart_week_content set mental_health_note = 'Other people''s pregnancy stories are not a forecast for yours. If a conversation leaves you more unsettled than informed, you can ask to change the subject.' where week_number = 19;
update care_chart_week_content set mental_health_note = 'A halfway marker can make the future feel more real. You can feel ready for some parts of motherhood and undecided about others without resolving everything this week.' where week_number = 20;
update care_chart_week_content set mental_health_note = 'If pregnancy is changing what you can do comfortably, needing help may take getting used to. You can name the task you need help with without apologising for your body.' where week_number = 21;
update care_chart_week_content set mental_health_note = 'Being busy can hide how you have been feeling. If low mood, numbness or a sense of being unlike yourself persists, Mental Health & Support can help you prepare to speak with a professional.' where week_number = 22;
update care_chart_week_content set mental_health_note = 'Money, housing or work concerns are real pressures, not failures to think positively. Sharing one concrete concern with someone able to help may be more useful than being told not to worry.' where week_number = 23;
update care_chart_week_content set mental_health_note = 'Pregnancy can change how you feel about touch and closeness. If you have a partner, you can describe what feels welcome now without promising that it will stay the same.' where week_number = 24;
update care_chart_week_content set mental_health_note = 'Advice can start to sound like competing instructions. You can ask your healthcare professional about care decisions and keep other people''s preferences from becoming another obligation.' where week_number = 25;
update care_chart_week_content set mental_health_note = 'Plans for leave or time away may stir feelings about work and identity. Wanting to stay connected to that part of yourself does not diminish your interest in your baby.' where week_number = 26;
update care_chart_week_content set mental_health_note = 'You may be imagining the mother you will become. Leave space for her to have your existing interests, limits and relationships, as well as new ones you cannot yet picture.' where week_number = 27;
update care_chart_week_content set mental_health_note = 'Before birth, it can help to choose someone you could speak honestly with afterward. You do not need to expect difficulty to make support easier to reach.' where week_number = 28;
update care_chart_week_content set mental_health_note = 'A growing list of preparations can make rest feel unfinished. You can decide which jobs matter to you and which expectations belong to other people.' where week_number = 29;
update care_chart_week_content set mental_health_note = 'Birth anticipation can include curiosity, excitement and fear. If fear keeps intruding on everyday life, tell your maternity professional what feels frightening so you can discuss support.' where week_number = 30;
update care_chart_week_content set mental_health_note = 'When nights feel long, worries can become louder. If you regularly cannot rest even when you have the chance, mention it to your healthcare professional rather than assuming you must put up with it.' where week_number = 31;
update care_chart_week_content set mental_health_note = 'A birth plan can express what helps you feel heard and safe. You can include how you want explanations given and who you would like involved in conversations.' where week_number = 32;
update care_chart_week_content set mental_health_note = 'You can want a particular birth experience while knowing plans may change. The outcome will not measure how well you prepared or how much you care.' where week_number = 33;
update care_chart_week_content set mental_health_note = 'Visitors may picture meeting the baby; you may be picturing recovery. Discussing privacy, meals and visits now can help others understand what support would actually look like for you.' where week_number = 34;
update care_chart_week_content set mental_health_note = 'If earlier loss or a difficult experience makes this stage complicated, you do not owe anyone uncomplicated excitement. Someone who knows your history may be a helpful person to speak with.' where week_number = 35;
update care_chart_week_content set mental_health_note = 'After birth, persistent low mood, anxiety, numbness or feeling unlike yourself deserves attention. You do not have to decide what it is; Mental Health & Support can help you put it into words and reach support.' where week_number = 36;
update care_chart_week_content set mental_health_note = 'As birth approaches, repeated requests for updates may become tiring. You can choose one person to share news, if that would give you more privacy.' where week_number = 37;
update care_chart_week_content set mental_health_note = 'Waiting can bring impatience even when you value this pregnancy. You do not need to turn the remaining days into a perfect memory or finish every preparation.' where week_number = 38;
update care_chart_week_content set mental_health_note = 'Before the focus shifts to birth and baby, your own voice still matters. You can tell the people supporting you what helps when you feel uncertain and how you want to be included.' where week_number = 39;
update care_chart_week_content set mental_health_note = 'Meeting your baby may bring an immediate rush of feeling, a quieter response or something hard to name. You do not have to perform happiness for visitors; your own experience deserves room too.' where week_number = 40;
update care_chart_week_content set mental_health_note = 'When care fills the day and night, support needs to include you. If someone offers help, you can ask for a meal, household task or company without needing to host them.' where week_number = 41;
update care_chart_week_content set mental_health_note = 'You need not wait for a scheduled check to mention emotional changes. If sadness, fear or numbness persists, worsens or disrupts daily life, contact your healthcare professional; Mental Health & Support can help you prepare.' where week_number = 42;
update care_chart_week_content set mental_health_note = 'Feeding can carry more emotional pressure than people acknowledge. Whatever your feeding situation, you can ask for practical support and say when advice is making you feel judged.' where week_number = 43;
update care_chart_week_content set mental_health_note = 'Bonding does not have to feel like a constant rush of love. If feeling distant troubles you or makes caring difficult, tell your healthcare professional; you can ask for support without judging yourself.' where week_number = 44;
update care_chart_week_content set mental_health_note = 'An unwanted intrusive thought is not the same as wanting to act. If thoughts frighten you, speak with a professional through Mental Health & Support. If you might act or anyone may be unsafe, seek urgent help now through Safety or emergency care.' where week_number = 45;
update care_chart_week_content set mental_health_note = 'Six weeks is not a deadline for feeling like yourself. At a health appointment, you can bring up your mind as well as your body, including feelings you have found difficult to explain.' where week_number = 46;
update care_chart_week_content set mental_health_note = 'You may have plenty of contact about the baby and little conversation about anything else. Wanting someone to ask about you is a real need, even when you are rarely physically alone.' where week_number = 47;
update care_chart_week_content set mental_health_note = 'If you share care, tiredness can leave conversations focused on who did what. Naming one task that needs a clear owner may be more useful than waiting for someone to notice it.' where week_number = 48;
update care_chart_week_content set mental_health_note = '"Sleep when the baby sleeps" may not describe the opportunities you have. You can ask for help that creates actual rest, and mention persistent difficulty sleeping despite an opportunity to your healthcare professional.' where week_number = 49;
update care_chart_week_content set mental_health_note = 'Touch can feel different when much of your day involves holding or feeding. You can want affection and space at different moments, and say what feels comfortable without a deadline for intimacy.' where week_number = 50;
update care_chart_week_content set mental_health_note = 'If work is approaching or has already resumed, relief and reluctance can coexist. Neither feeling decides how much you love your baby or value your work.' where week_number = 51;
update care_chart_week_content set mental_health_note = 'If you suddenly feel severely confused or hear or see things others do not, seek urgent medical help now. Contact emergency care and, if possible, ask a trusted person to stay with you; the existing Safety pathway can help you reach urgent support.' where week_number = 52;
update care_chart_week_content set mental_health_note = 'Three months does not mean the emotional adjustment is finished. If people have stopped checking in, you can tell someone what kind of contact would be welcome now.' where week_number = 53;
update care_chart_week_content set mental_health_note = 'Photos can bring feelings about a body still changing. You can decide when to be photographed and what to share without making your appearance a measure of recovery.' where week_number = 54;
update care_chart_week_content set mental_health_note = 'A short time away may feel welcome, uncomfortable or both. If someone trusted is caring for your baby, you can discuss what contact would help without turning the break into a test of independence.' where week_number = 55;
update care_chart_week_content set mental_health_note = 'Changing sleep can unsettle a day that had begun to feel familiar. Needing to revise the division of night care or daytime help does not mean your earlier arrangement failed.' where week_number = 56;
update care_chart_week_content set mental_health_note = 'Watching other families can make your own days seem disorganised. Their visible moments do not show their whole workload, support or circumstances; comparisons may be missing the information that matters.' where week_number = 57;
update care_chart_week_content set mental_health_note = 'Keeping appointments, supplies and everyone else''s needs in mind is work too. You can ask someone to own the remembering and planning, as well as carrying out a task.' where week_number = 58;
update care_chart_week_content set mental_health_note = 'Feeling persistently unlike yourself deserves a conversation even when you can explain how busy you are. Mental Health & Support can help you describe the change to a healthcare professional without choosing a diagnosis.' where week_number = 59;
update care_chart_week_content set mental_health_note = 'Thoughts about the birth may surface after the busiest early weeks. If memories are distressing or intrude on daily life, you can ask your healthcare professional for support without having to retell everything at once.' where week_number = 60;
update care_chart_week_content set mental_health_note = 'An interest from before motherhood may still feel like yours, or it may not. You can try a small return to it without committing to becoming your previous self again.' where week_number = 61;
update care_chart_week_content set mental_health_note = 'Changes in feeding can carry feelings alongside practical decisions. You can discuss both with someone supportive, without letting other people''s ideas of the "right" choice define your experience.' where week_number = 62;
update care_chart_week_content set mental_health_note = 'You may need friendships to fit smaller windows for a while. A message or brief conversation can keep a connection open without requiring you to organise a full outing.' where week_number = 63;
update care_chart_week_content set mental_health_note = 'If this week feels steady or enjoyable, there is no hidden problem you need to search for. You can notice which people or arrangements are making everyday life work for you.' where week_number = 64;
update care_chart_week_content set mental_health_note = 'If help has faded as your baby has grown, the workload may not have faded with it. You can ask for a new arrangement based on what your days require now.' where week_number = 65;
update care_chart_week_content set mental_health_note = 'At six months, "fine" may be accurate, or it may be the quickest answer. If there is more you want to say, Mental Health & Support can help you begin that conversation.' where week_number = 66;
update care_chart_week_content set mental_health_note = 'If new feeding routines are adding decisions to the day, it can help to share the planning. You do not have to be the only person researching, remembering and preparing.' where week_number = 67;
update care_chart_week_content set mental_health_note = 'Childcare decisions can involve trust, cost and necessity as well as preference. Mixed feelings do not tell you whether you have made a good or bad choice.' where week_number = 68;
update care_chart_week_content set mental_health_note = 'If your baby wants more closeness just as you want some space, both needs can matter. You can ask a trusted carer for help without making your wish for a break into a fault.' where week_number = 69;
update care_chart_week_content set mental_health_note = 'Being interrupted repeatedly can make even a small task feel demanding. If possible, ask for one protected stretch of time rather than trying to fit your needs into whatever remains.' where week_number = 70;
update care_chart_week_content set mental_health_note = 'If you are working, switching between roles can leave little sense of finishing anything. A realistic agreement about what can wait may help more than another effort to do both perfectly.' where week_number = 71;
update care_chart_week_content set mental_health_note = 'Money conversations can feel more personal when income or dependence has changed. You can ask for clarity about shared spending and your own needs without presenting them as extras.' where week_number = 72;
update care_chart_week_content set mental_health_note = 'If worry is making it hard to leave everyday care with someone trusted, or repeated checking takes over your day, speak with a professional. Mental Health & Support can help you explain what is happening.' where week_number = 73;
update care_chart_week_content set mental_health_note = 'Closeness with a partner may now need room around care and tiredness. A conversation about companionship, affection or space can start with what you want today, without a goal you must reach.' where week_number = 74;
update care_chart_week_content set mental_health_note = 'A baby''s new skills can draw everyone''s attention. Your week may also contain learning, frustration or satisfaction unrelated to milestones; there is room to talk about those things too.' where week_number = 75;
update care_chart_week_content set mental_health_note = 'If you feel guilty during time for yourself, that feeling need not decide how every spare moment is used. Your baby can matter deeply while you have interests beyond caring.' where week_number = 76;
update care_chart_week_content set mental_health_note = 'Different carers may handle ordinary routines differently. Where care is safe, agreeing what truly matters can leave less for you to supervise and more room for genuine sharing.' where week_number = 77;
update care_chart_week_content set mental_health_note = 'You may miss parts of your earlier life without wanting to undo this one. Saying exactly what you miss can help someone understand whether you want company, time, freedom or simply to be heard.' where week_number = 78;
update care_chart_week_content set mental_health_note = 'If the same small frustrations keep returning, consider whether an arrangement needs changing. A conversation about workload can be more useful than expecting yourself to become endlessly patient.' where week_number = 79;
update care_chart_week_content set mental_health_note = 'More outings do not automatically mean more connection. You might prefer a conversation with someone who can hear about your day without comparing babies or offering advice.' where week_number = 80;
update care_chart_week_content set mental_health_note = 'If opportunities feel narrower right now, it is understandable to notice that. You can keep an idea for later without making this a week when you must act on it.' where week_number = 81;
update care_chart_week_content set mental_health_note = 'With several people offering advice, you may find yourself defending every decision. You can choose a short response and save your attention for the questions that actually need an answer.' where week_number = 82;
update care_chart_week_content set mental_health_note = 'Irritability can be worth talking about too. If anger feels persistent, frightening or hard to manage, seek professional support through Mental Health & Support; immediate safety concerns need urgent help.' where week_number = 83;
update care_chart_week_content set mental_health_note = 'If you rarely get to finish a sentence or a thought, you may miss being listened to. You can ask someone for a little uninterrupted conversation about something that matters to you.' where week_number = 84;
update care_chart_week_content set mental_health_note = 'A feeding change can mark an ending as well as a practical shift. Relief, sadness or no strong feeling can each belong to your experience; you do not need to adopt someone else''s story.' where week_number = 85;
update care_chart_week_content set mental_health_note = 'Body comments may continue long after birth. You can ask people to leave weight and "getting back" out of conversations, even when they intend a compliment.' where week_number = 86;
update care_chart_week_content set mental_health_note = 'If you are arranging childcare, choosing a workable option may still involve compromise. Needing care that fits your circumstances does not require you to feel pleased about every part of it.' where week_number = 87;
update care_chart_week_content set mental_health_note = 'Plans with a baby can change at short notice. If cancellations are affecting a friendship, explaining what would make contact easier may help more than repeatedly promising a bigger visit.' where week_number = 88;
update care_chart_week_content set mental_health_note = 'If you feel low or numb even during things you expected to enjoy, you can tell a healthcare professional. Mental Health & Support can help you find words; you do not need a label first.' where week_number = 89;
update care_chart_week_content set mental_health_note = 'Approaching a first birthday may bring memories of pregnancy or birth. You can decide how much to revisit and who, if anyone, you want alongside you.' where week_number = 90;
update care_chart_week_content set mental_health_note = 'A birthday can become another project to manage. You can choose a scale that fits your energy and resources without using the celebration to prove what this year meant.' where week_number = 91;
update care_chart_week_content set mental_health_note = 'One year can hold pride, affection, exhaustion and unfinished feelings together. A happy milestone is not proof that everything feels okay; support remains available for whatever you want to talk about.' where week_number = 92;
update care_chart_week_content set mental_health_note = 'The first birthday does not end your adjustment to motherhood. You can keep asking for help with arrangements that still make daily life harder than they need to be.' where week_number = 93;
update care_chart_week_content set mental_health_note = 'If your child is exploring more, being continually alert may feel tiring in a new way. Sharing supervision includes giving you time when you are genuinely off duty.' where week_number = 94;
update care_chart_week_content set mental_health_note = 'A stronger preference for one carer can stir unexpected feelings. Your child''s response in a particular moment is not a verdict on the relationship you are building.' where week_number = 95;
update care_chart_week_content set mental_health_note = 'You may enjoy parts of work that have nothing to do with being a parent. You do not have to explain that enjoyment as something you do only for your family.' where week_number = 96;
update care_chart_week_content set mental_health_note = 'If you are home with your child, the repetition of care may be less visible than paid work. You can name that workload when talking about time, rest and shared responsibilities.' where week_number = 97;
update care_chart_week_content set mental_health_note = 'A difficult day in public can feel different under other people''s eyes. You do not owe bystanders an explanation of your child''s feelings or a performance of perfect composure.' where week_number = 98;
update care_chart_week_content set mental_health_note = 'If you miss adult company, another parent is only one possible source of connection. A friend who shares your interests may offer a welcome conversation beyond this stage of care.' where week_number = 99;
update care_chart_week_content set mental_health_note = 'If a child''s "no" brings up strong feelings for you, noticing that can be useful without becoming self-criticism. You can ask for support with the moments you find hardest.' where week_number = 100;
update care_chart_week_content set mental_health_note = 'Some weeks are full of maintenance rather than visible achievements. Keeping a household and caring for a child takes time even when there is little new to report.' where week_number = 101;
update care_chart_week_content set mental_health_note = 'If anxiety is shrinking the places you go or the things you feel able to do, speak with a professional. Mental Health & Support can help you describe the effect on your day.' where week_number = 102;
update care_chart_week_content set mental_health_note = 'You can care about your child''s learning without filling every gap with an activity. Your own time does not have to become an endless search for the next useful thing.' where week_number = 103;
update care_chart_week_content set mental_health_note = 'A family routine may work for everyone except the person holding it together. You can revisit an arrangement that looks successful from the outside but leaves too little room for you.' where week_number = 104;
update care_chart_week_content set mental_health_note = 'Clothes that fit your life now may feel different from clothes that represent an earlier chapter. Choosing comfort does not require a decision about how you must feel about your body.' where week_number = 105;
update care_chart_week_content set mental_health_note = 'If there are two adults sharing care, "just tell me what to do" can still leave one person managing. A whole responsibility can be shared, including noticing when it needs doing.' where week_number = 106;
update care_chart_week_content set mental_health_note = 'Family traditions may bring warmth, pressure or both. You can keep the parts that matter to you and discuss a smaller version of what has become too demanding.' where week_number = 107;
update care_chart_week_content set mental_health_note = 'If a friend seems to have more freedom, envy may point to something you miss. You can name that need without judging either her life or your own.' where week_number = 108;
update care_chart_week_content set mental_health_note = 'Your child''s frustration can be loud without making your response a public exam. If particular situations repeatedly overwhelm you, it is reasonable to ask for practical help with them.' where week_number = 109;
update care_chart_week_content set mental_health_note = 'A little more independence may bring relief and a sense of being less needed. You can have both feelings without holding back your child or rushing yourself past the change.' where week_number = 110;
update care_chart_week_content set mental_health_note = 'If you are thinking about study or work, interest is enough for an initial conversation. You do not need a complete plan before finding out what might fit your circumstances.' where week_number = 111;
update care_chart_week_content set mental_health_note = 'If low mood or disconnection has quietly become familiar, it is still worth raising. You can use Mental Health & Support to prepare for a professional conversation, even long after the newborn months.' where week_number = 112;
update care_chart_week_content set mental_health_note = 'Being the default contact for every question can keep you mentally on call. You can discuss which decisions someone else can make without checking with you first.' where week_number = 113;
update care_chart_week_content set mental_health_note = 'You may want companionship without organising it all yourself. It is okay to tell someone, "I''d like to see you, but could you make the plan this time?"' where week_number = 114;
update care_chart_week_content set mental_health_note = 'If another pregnancy is being discussed around you, your own wishes deserve space. You can be undecided or private; other people''s preferred timetable does not have to become yours.' where week_number = 115;
update care_chart_week_content set mental_health_note = 'When sleep is interrupted again, frustration does not erase your affection for your child. It may be time to revisit who can help and what can be postponed.' where week_number = 116;
update care_chart_week_content set mental_health_note = 'You may notice that certain kinds of help create more work afterward. You can explain what would actually lighten your day, even when an offer was well intended.' where week_number = 117;
update care_chart_week_content set mental_health_note = 'At eighteen months, there is no "by now you should be fine" rule. Your wellbeing still deserves attention, whether life feels settled or there is something you want help with.' where week_number = 118;
update care_chart_week_content set mental_health_note = 'As your child expresses more preferences, your days may involve more negotiation. You are allowed to have preferences too, including how you use a small piece of your own time.' where week_number = 119;
update care_chart_week_content set mental_health_note = 'Rest can feel difficult when someone always needs something. If possible, agree on a period when another trusted adult holds responsibility, so a break does not depend on listening for the next request.' where week_number = 120;
update care_chart_week_content set mental_health_note = 'If touch feels constant, you can ask for a little physical space while ensuring your child is cared for. Wanting that space need not be explained as a lack of affection.' where week_number = 121;
update care_chart_week_content set mental_health_note = 'A return to work can mean returning to a changed version of the role or yourself. You can ask questions and need time to settle without proving you are unaffected by the transition.' where week_number = 122;
update care_chart_week_content set mental_health_note = 'If work is not part of this season, you can still want recognition, learning or a project of your own. Those wishes do not need to be justified through income.' where week_number = 123;
update care_chart_week_content set mental_health_note = 'When worry or sadness keeps getting postponed behind family needs, it can become harder to mention. Mental Health & Support can help you start with what has changed and how it affects you.' where week_number = 124;
update care_chart_week_content set mental_health_note = 'Play does not have to be absorbing for you every minute to be meaningful for your child. You can enjoy some kinds of time together more than others.' where week_number = 125;
update care_chart_week_content set mental_health_note = 'If relatives disagree with an ordinary parenting choice, you can listen without opening every decision for debate. A boundary can be brief and still respectful.' where week_number = 126;
update care_chart_week_content set mental_health_note = 'A household task may need doing, but it does not always need you. Sharing care can include allowing someone else to develop their own way of managing a responsibility.' where week_number = 127;
update care_chart_week_content set mental_health_note = 'If your child needs extra appointments or support, the coordination can take up a great deal of thought. You can ask someone to help with the administration as well as ask how you are.' where week_number = 128;
update care_chart_week_content set mental_health_note = 'Friendships can change when schedules and priorities differ. You can miss an earlier closeness and still look for a way of connecting that fits both lives now.' where week_number = 129;
update care_chart_week_content set mental_health_note = 'If you have snapped during a hard moment, you can return and acknowledge it without making your child responsible for your feelings. Repeated moments that worry you deserve support, not secrecy.' where week_number = 130;
update care_chart_week_content set mental_health_note = 'You do not have to turn a hobby into progress, income or a family activity. Something can be yours simply because you like spending time on it.' where week_number = 131;
update care_chart_week_content set mental_health_note = 'Feeling unheard in a relationship can be lonely even in a busy home. Where it feels safe, you can name what you want understood before trying to solve the practical disagreement.' where week_number = 132;
update care_chart_week_content set mental_health_note = 'If returning to a familiar interest feels awkward, you may simply be out of practice or want something different now. You can explore without deciding what it says about who you are.' where week_number = 133;
update care_chart_week_content set mental_health_note = 'Questions about another baby can touch private feelings about health, loss, money or desire. "We''re keeping that private" is a complete answer if you want it to be.' where week_number = 134;
update care_chart_week_content set mental_health_note = 'When a child''s routine changes, everyone may need a different arrangement. Your need for reliable time is part of that discussion, alongside what works for your child.' where week_number = 135;
update care_chart_week_content set mental_health_note = 'Looking for paid work can bring uncertainty about skills or opportunity. You can ask for practical information without treating every setback as a judgement of your worth.' where week_number = 136;
update care_chart_week_content set mental_health_note = 'If you are carrying care alone, advice to "share the load" may miss your circumstances. Support can start with a specific person or service helping with one feasible part of the week.' where week_number = 137;
update care_chart_week_content set mental_health_note = 'Some family expectations are so familiar that they barely sound like requests. You can pause before agreeing and consider whether the time or energy is actually available.' where week_number = 138;
update care_chart_week_content set mental_health_note = 'If getting out takes more planning than staying home, isolation can happen without a deliberate choice. A simpler form of contact may fit better than waiting for the ideal outing.' where week_number = 139;
update care_chart_week_content set mental_health_note = 'Persistent sadness, anxiety or feeling unlike yourself deserves attention at this stage too. Mental Health & Support can help you prepare to speak with a healthcare professional; the newborn period is not a deadline for asking.' where week_number = 140;
update care_chart_week_content set mental_health_note = 'A new childcare arrangement can affect your own routine as much as your child''s. You can leave room to adjust rather than expecting the freed time to become productive immediately.' where week_number = 141;
update care_chart_week_content set mental_health_note = 'You may feel differently about motherhood than you did a year ago. Changing your mind about what suits you does not invalidate the choices that worked earlier.' where week_number = 142;
update care_chart_week_content set mental_health_note = 'As a second birthday approaches, comparing your child with others can spill into judging yourself. Questions about their development belong in a professional conversation, not a verdict on your parenting.' where week_number = 143;
update care_chart_week_content set mental_health_note = 'A second birthday marks your child''s growth and another year of your own life. You can make room for how you are doing, without needing the answer to match the celebration.' where week_number = 144;
update care_chart_week_content set mental_health_note = 'With a two-year-old, a small decision can become a lengthy negotiation. If you feel worn down, consider which adult responsibilities can be simplified or shared rather than expecting more patience from yourself.' where week_number = 145;
update care_chart_week_content set mental_health_note = 'Your child may ask for independence and then need closeness again. Your feelings about those shifts can change too; there is no single response you must maintain.' where week_number = 146;
update care_chart_week_content set mental_health_note = 'If toilet learning is becoming a topic, other people''s timelines may add pressure. You can seek practical guidance without making the process a measure of your child''s worth or your competence.' where week_number = 147;
update care_chart_week_content set mental_health_note = 'A difficult handover can stay with you after your child has moved into their day. You can ask the carer for a clear update arrangement instead of spending the whole separation guessing.' where week_number = 148;
update care_chart_week_content set mental_health_note = 'When parenting advice contradicts itself, more reading may leave you less certain. You can choose a trusted source for the actual question and let the rest of the commentary wait.' where week_number = 149;
update care_chart_week_content set mental_health_note = 'If your child prefers another trusted adult for something, there may be both relief and a sting. One preference in one moment does not sum up your place in their life.' where week_number = 150;
update care_chart_week_content set mental_health_note = 'The way your body feels now may affect confidence, comfort or intimacy. You can speak about those effects without accepting that every change is something you must quietly live with.' where week_number = 151;
update care_chart_week_content set mental_health_note = 'Financial independence can mean different things in different families. If money limits your choices, you can name that concern and seek practical support without being told that gratitude should make it disappear.' where week_number = 152;
update care_chart_week_content set mental_health_note = 'Your family''s size is not a question you owe others an answer to. You can hold hopes, limits or uncertainty privately, even when the questions sound friendly.' where week_number = 153;
update care_chart_week_content set mental_health_note = 'If you live with extended family, being surrounded by people may still leave little privacy. Asking for some uninterrupted space can be about your needs without rejecting their care.' where week_number = 154;
update care_chart_week_content set mental_health_note = 'If your child tells you to go away in a frustrated moment, it may still hurt. You can acknowledge that feeling with another adult without asking your child to reassure you.' where week_number = 155;
update care_chart_week_content set mental_health_note = 'A quieter night does not necessarily remove the need for daytime support. You can revisit the whole workload rather than treating sleep as the only reason you are allowed to feel tired.' where week_number = 156;
update care_chart_week_content set mental_health_note = 'When you are the one who remembers everyone''s preferences, yours can go unasked. You might name something you would choose this week, even if it is small.' where week_number = 157;
update care_chart_week_content set mental_health_note = 'A partner or friend may miss that conversation has become mostly logistics. If you want more connection, you can ask for time to talk about something beyond what needs doing next.' where week_number = 158;
update care_chart_week_content set mental_health_note = 'Purpose can come from care, paid work, learning, relationships or making something. You do not have to choose one source that explains all of who you are.' where week_number = 159;
update care_chart_week_content set mental_health_note = 'If feeling flat, on edge or unlike yourself has become your usual backdrop, you can still seek help. Mental Health & Support can help you explain it; you need not wait for things to become unbearable.' where week_number = 160;
update care_chart_week_content set mental_health_note = 'If several people rely on you, every request may sound equally urgent. You can ask what truly needs you today and discuss who else can take responsibility for the rest.' where week_number = 161;
update care_chart_week_content set mental_health_note = 'Repeated illness or disrupted childcare can unravel carefully made plans. Disappointment about your lost time is allowed alongside concern for your child; both parts of the day matter.' where week_number = 162;
update care_chart_week_content set mental_health_note = 'Your child may be learning that people have different preferences. Your own likes and dislikes can stay visible too, without every shared activity becoming your first choice.' where week_number = 163;
update care_chart_week_content set mental_health_note = 'If public outings feel like a performance for other adults, a familiar place or trusted companion may feel easier. You can choose what fits your capacity without explaining it to everyone.' where week_number = 164;
update care_chart_week_content set mental_health_note = 'You may want more challenge in one part of life and less demand in another. Wanting an interesting project does not mean you no longer need help with care.' where week_number = 165;
update care_chart_week_content set mental_health_note = 'Time that becomes available through childcare can include rest. You do not have to account for every hour by producing something that another person can see.' where week_number = 166;
update care_chart_week_content set mental_health_note = 'If guilt appears when you set a reasonable boundary, you can consider the boundary on its merits. Feeling uncomfortable does not automatically mean you have been unkind.' where week_number = 167;
update care_chart_week_content set mental_health_note = 'When a friend asks how you are, you can give more than an update about your child. Your interests, uncertainties and good news are part of the friendship too.' where week_number = 168;
update care_chart_week_content set mental_health_note = 'Some phases call for keeping things workable rather than improving everything. You can leave a nonessential project unfinished without turning it into evidence about your ability to cope.' where week_number = 169;
update care_chart_week_content set mental_health_note = 'If you are repeatedly getting more upset than you want to, you can ask for support before it becomes a crisis. Mental Health & Support can help you describe the difficult moments to a professional.' where week_number = 170;
update care_chart_week_content set mental_health_note = 'Your child may want the same game again when you want variety. Different preferences can exist without either of you being wrong; another carer may be able to share that stretch of play.' where week_number = 171;
update care_chart_week_content set mental_health_note = 'A family outing can involve hidden preparation and clearing up. When planning something enjoyable, it is fair to include who will do that work so the enjoyment has room for you too.' where week_number = 172;
update care_chart_week_content set mental_health_note = 'If you are considering a work change, caring responsibilities are relevant information, not something to apologise for. You can ask what an opportunity requires before deciding whether it fits.' where week_number = 173;
update care_chart_week_content set mental_health_note = 'If someone close raises a concern about how you seem, you can ask what they have noticed. Their concern is not a diagnosis; it may be a starting point for a professional conversation.' where week_number = 174;
update care_chart_week_content set mental_health_note = 'You can take pleasure in your child''s growing independence and miss an earlier stage. A change does not need to be wholly welcome or wholly sad to be meaningful.' where week_number = 175;
update care_chart_week_content set mental_health_note = 'If your family is navigating a move, separation or other change, your feelings need somewhere to go too. A trusted adult can be that listener without your child carrying the worry.' where week_number = 176;
update care_chart_week_content set mental_health_note = 'Boundaries around visitors, photos or family plans may need repeating as circumstances change. A previous "yes" does not commit you to the same arrangement forever.' where week_number = 177;
update care_chart_week_content set mental_health_note = 'Having more experience as a mother does not mean knowing what to do in every new situation. You can ask a question without first proving that you have tried everything yourself.' where week_number = 178;
update care_chart_week_content set mental_health_note = 'If being needed has occupied most of your time, free time may feel unfamiliar. You can explore what you enjoy now without turning the search into another task to get right.' where week_number = 179;
update care_chart_week_content set mental_health_note = 'If scary unwanted thoughts are distressing, tell a professional; Mental Health & Support can help you begin. You need not interpret them yourself. If you might act on harm or cannot keep yourself or your child safe, seek urgent help now through Safety or emergency care.' where week_number = 180;
update care_chart_week_content set mental_health_note = 'A busy week can leave little space for ordinary affection or conversation with a partner. Where the relationship feels safe, saying what kind of connection you miss can open a more specific conversation.' where week_number = 181;
update care_chart_week_content set mental_health_note = 'If you feel afraid or controlled in a relationship, you do not have to confront the person to deserve help. Seek confidential professional support when safe; if there is immediate danger, contact emergency services or the existing Safety pathway.' where week_number = 182;
update care_chart_week_content set mental_health_note = 'Other parents'' plans for preschool or activities may not suit your family. You can consider your child''s needs and your circumstances without entering a race to arrange the most.' where week_number = 183;
update care_chart_week_content set mental_health_note = 'When an old ambition returns, you can be curious about it without promising a major change. Finding out more is a meaningful step even if the timing is not right yet.' where week_number = 184;
update care_chart_week_content set mental_health_note = 'If you are supporting an older relative as well as your child, people may overlook the combined demands. You can describe the whole workload when asking for help, rather than each task in isolation.' where week_number = 185;
update care_chart_week_content set mental_health_note = 'A helpful arrangement is worth maintaining even when things feel easier. You do not have to give up support the moment it starts making life more manageable.' where week_number = 186;
update care_chart_week_content set mental_health_note = 'As your child becomes more verbal, family conversations may change. Your voice still belongs in them, including a preference that is not immediately convenient for everyone else.' where week_number = 187;
update care_chart_week_content set mental_health_note = 'If you hear yourself using words from your own childhood, you may want to keep some and change others. You can reflect on this with support without judging your whole history or parenting.' where week_number = 188;
update care_chart_week_content set mental_health_note = 'Your interests may have shifted over these years, and some may have stayed steady. You do not need a complete new identity or a return to the old one.' where week_number = 189;
update care_chart_week_content set mental_health_note = 'Support does not have an expiry date. If something feels unlike you now, or an earlier difficulty returns, Mental Health & Support can help you reach a person who can listen and help.' where week_number = 190;
update care_chart_week_content set mental_health_note = 'Looking back can make missed opportunities stand out more than ordinary days. You can remember what was difficult without using hindsight to demand choices you could not realistically make then.' where week_number = 191;
update care_chart_week_content set mental_health_note = 'As this weekly series nears its end, consider which connections you want to keep active. Support can be part of everyday life, not something reserved for a particularly hard week.' where week_number = 192;
update care_chart_week_content set mental_health_note = 'A third birthday may bring practical changes as well as memories. You can decide which transitions need attention now and which plans can stay open a little longer.' where week_number = 193;
update care_chart_week_content set mental_health_note = 'If you want a conversation about your wellbeing, you do not need a new milestone or a crisis to justify it. Mental Health & Support remains a place to prepare for that next step.' where week_number = 194;
update care_chart_week_content set mental_health_note = 'You do not have to summarise three years as wonderful, difficult or transformative. Particular moments may mean different things, and some experiences may still be finding their words.' where week_number = 195;
update care_chart_week_content set mental_health_note = 'Your child''s third birthday is a marker, not a finish line for your own growth or care. There is room ahead for your relationships, interests and wellbeing, with support whenever you need it.' where week_number = 196;
